CREATE OR ALTER PROCEDURE [dbo].[uspOutboundMessage_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @IntegrationChannelId UNIQUEIDENTIFIER = NULL
	, @MessageType NVARCHAR(MAX) = NULL
	, @MessageStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[IntegrationChannelId]
			, t.[ExternalConversationId]
			, t.[RecipientExternalId]
			, t.[MessageType]
			, t.[PayloadJson]
			, t.[QueuedAt]
			, t.[SentAt]
			, t.[MessageStatus]
			, t.[RetryCount]
			, t.[IdempotencyKey]
			, t.[CorrelationId]
			, t.[ProviderMessageId]
			, t.[LastError]
			, t.[CreatedDate]
		FROM [dbo].[OutboundMessage] AS t
		
		WHERE 1 = 1
			AND (@IntegrationChannelId IS NULL OR t.[IntegrationChannelId] = @IntegrationChannelId)
			AND (ISNULL(@MessageType, '') = '' OR t.[MessageType] = @MessageType)
			AND (ISNULL(@MessageStatus, '') = '' OR t.[MessageStatus] = @MessageStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'integrationChannelId' THEN r.[IntegrationChannelId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'integrationChannelId' THEN r.[IntegrationChannelId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'externalConversationId' THEN r.[ExternalConversationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'externalConversationId' THEN r.[ExternalConversationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'recipientExternalId' THEN r.[RecipientExternalId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'recipientExternalId' THEN r.[RecipientExternalId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'messageType' THEN r.[MessageType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'messageType' THEN r.[MessageType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'payloadJson' THEN r.[PayloadJson] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'payloadJson' THEN r.[PayloadJson] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'queuedAt' THEN r.[QueuedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'queuedAt' THEN r.[QueuedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sentAt' THEN r.[SentAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sentAt' THEN r.[SentAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'messageStatus' THEN r.[MessageStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'messageStatus' THEN r.[MessageStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'retryCount' THEN r.[RetryCount] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'retryCount' THEN r.[RetryCount] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'idempotencyKey' THEN r.[IdempotencyKey] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'idempotencyKey' THEN r.[IdempotencyKey] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'correlationId' THEN r.[CorrelationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'correlationId' THEN r.[CorrelationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'providerMessageId' THEN r.[ProviderMessageId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'providerMessageId' THEN r.[ProviderMessageId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lastError' THEN r.[LastError] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lastError' THEN r.[LastError] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
